import type { Node as ProseMirrorNode, Schema } from '@tiptap/pm/model'
import type { Transaction } from '@tiptap/pm/state'

import { getCurrentUser } from '@nextcloud/auth'
import { InputRule, mergeAttributes, Node } from '@tiptap/core'
import { DOMParser } from '@tiptap/pm/model'
import { TextSelection } from '@tiptap/pm/state'
import markdownit from '../markdownit/index.js'
import { commentBubbleKey } from '../plugins/commentBubble.ts'
import { generateReferenceId, isEmptyComment, isInsideCommentOrFootnote, removeCommentDraft } from '../plugins/referenceHelpers.ts'

declare module '@tiptap/core' {
	interface Commands<ReturnType> {
		commentReference: {
			insertComment: () => ReturnType
			addOrUpdateCommentReply: (comment: ProseMirrorNode, markdownText: string, itemIndex?: number) => ReturnType
			deleteCommentReply: (comment: ProseMirrorNode, itemIndex: number) => ReturnType
		}
	}
}

function createEmptyComment(schema: Schema, referenceId: string): ProseMirrorNode {
	const currentUser = getCurrentUser()
	const commentItem = schema.nodes.commentItem.create({
		author: currentUser?.uid ?? '',
		authorLabel: currentUser?.displayName ?? localStorage.getItem('nick') ?? '',
		timestamp: new Date().toISOString(),
	}, schema.nodes.paragraph.create())
	return schema.nodes.comment.create({ referenceId }, commentItem)
}

// Append a comment to the comments container, creating the container before footnotes if missing
function insertIntoCommentsContainer(tr: Transaction, comment: ProseMirrorNode): void {
	let commentsInsidePos = -1
	let footnotesStartPos = -1
	tr.doc.forEach((child, offset) => {
		if (child.type.name === 'comments') {
			commentsInsidePos = offset + child.nodeSize - 1
		}
		if (child.type.name === 'footnotes') {
			footnotesStartPos = offset
		}
	})
	if (commentsInsidePos !== -1) {
		tr.insert(commentsInsidePos, comment)
		return
	}
	const comments = tr.doc.type.schema.nodes.comments.create(null, comment)
	tr.insert(footnotesStartPos !== -1 ? footnotesStartPos : tr.doc.content.size, comments)
}

const CommentReference = Node.create({
	name: 'commentReference',
	group: 'inline',
	inline: true,
	atom: true,

	addAttributes() {
		return {
			referenceId: {
				default: '',
				parseHTML: (el) => el.getAttribute('data-reference-id') ?? '',
				renderHTML: (attrs) => ({
					'data-reference-id': attrs.referenceId,
				}),
			},
		}
	},

	parseHTML() {
		return [{ tag: 'sup[data-type="comment-reference"]' }]
	},

	renderHTML({ node, HTMLAttributes }) {
		const id = node.attrs.referenceId
		return [
			'sup',
			mergeAttributes(HTMLAttributes, {
				'data-type': 'comment-reference',
				id: `cref-${id}`,
			}),
			[
				'a',
				{ href: `#c-${id}`, class: 'comment-ref', role: 'doc-noteref', title: id },
				'💬',
			],
		]
	},

	addNodeView() {
		return ({ node, editor }) => {
			const id = node.attrs.referenceId
			const sup = document.createElement('sup')
			sup.dataset.type = 'comment-reference'
			sup.dataset.referenceId = id
			sup.id = `cref-${id}`

			const button = document.createElement('button')
			button.type = 'button'
			button.className = 'comment-ref'
			button.setAttribute('contenteditable', 'false')
			button.textContent = '💬'
			button.addEventListener('click', () => editor.commands.openCommentBubble(id))
			sup.appendChild(button)
			return { dom: sup, contentDOM: null }
		}
	},

	toMarkdown(state, node) {
		state.write(`[^${node.attrs.referenceId}]`)
	},

	addCommands() {
		return {
			insertComment: () => ({ state, chain, dispatch, editor }) => {
				if (editor.storage.annotationsVisibility?.hidden || isInsideCommentOrFootnote(state)) {
					return false
				}

				const referenceId = generateReferenceId(state.doc, 'comment')
				if (!referenceId) {
					return false
				}

				// Clear any stale draft from a previous comment that used this ID
				removeCommentDraft(referenceId)

				// In can-check mode, the above guards are sufficient
				if (!dispatch) {
					return true
				}

				const newComment = createEmptyComment(state.schema, referenceId)

				let c = chain()
					.insertContentAt(state.selection.to, { type: 'commentReference', attrs: { referenceId } })
					.command(({ tr }) => {
						insertIntoCommentsContainer(tr, newComment)
						return true
					})

				// Move selection/cursor to reference to avoid it being inside the hidden comments container
				c = c.command(({ state, dispatch }) => {
					let nodeStart: number | null = null
					let refEnd: number | null = null
					state.doc.descendants((node, pos) => {
						if (refEnd !== null) {
							return false
						}
						if (node.type.name === 'commentReference' && node.attrs.referenceId === referenceId) {
							nodeStart = pos
							refEnd = pos + node.nodeSize
							return false
						}
					})
					if (nodeStart === null || refEnd === null) {
						return false
					}
					if (dispatch) {
						dispatch(state.tr
							.setSelection(TextSelection.near(state.doc.resolve(refEnd)))
							// Open comment bubble
							.setMeta(commentBubbleKey, { active: { referenceId, nodeStart } }))
					}
					return true
				})

				return c
					.scrollIntoView()
					.run()
			},
			addOrUpdateCommentReply: (comment: ProseMirrorNode, markdownText: string, itemIndex?: number) => ({ state, dispatch }) => {
				if (!markdownText) {
					return false
				}

				// serialize Markdown from content to a ProseMirror Fragment
				const html = markdownit.render(markdownText)
				const dom = document.createElement('div')
				dom.innerHTML = html
				const fragment = DOMParser.fromSchema(this.editor.schema).parse(dom)
				const content = fragment.content

				if (content.textBetween(0, content.size, ' ').trim() === '') {
					return false
				}

				const currentUser = getCurrentUser()
				const author = currentUser?.uid ?? ''
				const authorLabel = currentUser?.displayName ?? localStorage.getItem('nick') ?? ''
				const timestamp = new Date().toISOString()

				let commentPos = -1
				state.doc.descendants((node, pos) => {
					if (commentPos !== -1) {
						return false
					}
					if (node === comment) {
						commentPos = pos
						return false
					}
				})
				if (commentPos === -1) {
					return false
				}

				if (itemIndex !== undefined && itemIndex >= comment.childCount) {
					// Given itemIndex does not exist
					return false
				}

				// Get item to update if itemIndex is provided
				let itemPos = commentPos + 1
				let item: ProseMirrorNode
				if (itemIndex !== undefined) {
					for (let i = 0; i < itemIndex; i++) {
						itemPos += comment.child(i).nodeSize
					}
					item = comment.child(itemIndex)
				} else {
					item = comment.firstChild!
				}

				const tr = state.tr
				const shouldAppendNewReply = itemIndex === undefined && !isEmptyComment(comment)
				if (shouldAppendNewReply) {
					// Append a new reply item
					const commentItemType = state.schema.nodes.commentItem
					const newItem = commentItemType.create({ author, authorLabel, timestamp }, content)
					tr.insert(commentPos + comment.nodeSize - 1, newItem)
				} else {
					// Replace existing item if itemIndex is given or if only one empty item
					// exists (i.e. straight after addComment() command was called)
					tr.setNodeMarkup(itemPos, null, { ...item.attrs, timestamp })
					tr.replaceWith(itemPos + 1, itemPos + item.nodeSize - 1, content)
				}

				if (dispatch) {
					dispatch(tr)
				}
				return true
			},
			deleteCommentReply: (comment: ProseMirrorNode, itemIndex: number) => ({ state, dispatch }) => {
				let commentPos = -1
				state.doc.descendants((node, pos) => {
					if (commentPos !== -1) {
						return false
					}
					if (node === comment) {
						commentPos = pos
						return false
					}
				})

				if (commentPos === -1) {
					return false
				}

				if (itemIndex >= comment.childCount) {
					return false
				}

				const tr = state.tr

				if (comment.childCount === 1) {
					// Deleting the last item - remove the reference instead;
					// commentsCleanup will remove the orphaned comment node
					let refPos = -1, refSize = 0
					state.doc.descendants((node, pos) => {
						if (node.type.name === 'commentReference' && node.attrs.referenceId === comment.attrs.referenceId) {
							refPos = pos
							refSize = node.nodeSize
							return false
						}
					})
					if (refPos !== -1) {
						tr.delete(refPos, refPos + refSize)
					}
				} else {
					let itemPos = commentPos + 1
					for (let i = 0; i < itemIndex; i++) {
						itemPos += comment.child(i).nodeSize
					}
					const item = comment.child(itemIndex)
					tr.delete(itemPos, itemPos + item.nodeSize)
				}

				if (dispatch) {
					dispatch(tr)
				}
				return true
			},
		}
	},

	addKeyboardShortcuts() {
		return {
			'Mod-Alt-m': () => this.editor.commands.insertComment(),
		}
	},

	addInputRules() {
		return [
			new InputRule({
				find: /\[\?\]$/,
				handler: ({ state, range, chain }) => {
					if (isInsideCommentOrFootnote(state)) {
						return null
					}
					chain()
						.deleteRange({ from: range.from, to: range.to })
						.insertComment()
						.run()
				},
			}),
		]
	},
})

export default CommentReference
