<template>
	<NodeViewWrapper
		data-text-el="table-header"
		as="th"
		:dir="dir"
		:style="align">
		<div>
			<NodeViewContent class="content" />
			<NcActions
				v-if="isEditable"
				ref="menu"
				size="small"
				variant="tertiary-no-background"
				data-text-table-actions="header">
				<NcActionButtonGroup>
					<NcActionButton
						data-text-table-action="align-column-left"
						:aria-label="t('text', 'Left align column')"
						type="radio"
						value="left"
						:modelValue="node.attrs.align"
						@click="setAlignLeft">
						<template #icon>
							<AlignHorizontalLeft />
						</template>
					</NcActionButton>
					<NcActionButton
						data-text-table-action="align-column-center"
						:aria-label="t('text', 'Center align column')"
						type="radio"
						value="center"
						:modelValue="node.attrs.align"
						@click="setAlignCenter">
						<template #icon>
							<AlignHorizontalCenter />
						</template>
					</NcActionButton>
					<NcActionButton
						data-text-table-action="align-column-right"
						:aria-label="t('text', 'Right align column')"
						type="radio"
						value="right"
						:modelValue="node.attrs.align"
						@click="setAlignRight">
						<template #icon>
							<AlignHorizontalRight />
						</template>
					</NcActionButton>
				</NcActionButtonGroup>
				<NcActionButton
					data-text-table-action="sort-column-asc"
					closeAfterClick
					@click="sortColumnAsc">
					<template #icon>
						<SortAscending />
					</template>
					{{ t('text', 'Sort ascending') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="sort-column-desc"
					closeAfterClick
					@click="sortColumnDesc">
					<template #icon>
						<SortDescending />
					</template>
					{{ t('text', 'Sort descending') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="add-column-before"
					closeAfterClick
					@click="addColumnBefore">
					<template #icon>
						<TableAddColumnBefore />
					</template>
					{{ t('text', 'Add column before') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="add-column-after"
					closeAfterClick
					@click="addColumnAfter">
					<template #icon>
						<TableAddColumnAfter />
					</template>
					{{ t('text', 'Add column after') }}
				</NcActionButton>
				<NcActionButton
					data-text-table-action="remove-column"
					closeAfterClick
					@click="deleteColumn">
					<template #icon>
						<TrashCan />
					</template>
					{{ t('text', 'Delete this column') }}
				</NcActionButton>
			</NcActions>
		</div>
	</NodeViewWrapper>
</template>

<script>
import { t } from '@nextcloud/l10n'
import { NodeViewContent, nodeViewProps, NodeViewWrapper } from '@tiptap/vue-3'
import NcActionButton from '@nextcloud/vue/components/NcActionButton'
import NcActionButtonGroup from '@nextcloud/vue/components/NcActionButtonGroup'
import NcActions from '@nextcloud/vue/components/NcActions'
import {
	AlignHorizontalCenter,
	AlignHorizontalLeft,
	AlignHorizontalRight,
	SortAscending,
	SortDescending,
	TableAddColumnAfter,
	TableAddColumnBefore,
	TrashCan,
} from '../../components/icons.js'

export default {
	name: 'TableHeaderView',
	components: {
		AlignHorizontalCenter,
		AlignHorizontalLeft,
		AlignHorizontalRight,
		TrashCan,
		NcActionButton,
		NcActionButtonGroup,
		NcActions,
		NodeViewWrapper,
		NodeViewContent,
		TableAddColumnBefore,
		TableAddColumnAfter,
		SortAscending,
		SortDescending,
	},

	props: nodeViewProps,

	data() {
		return {
			isEditable: false,
		}
	},

	computed: {
		align() {
			return { 'text-align': this.node.attrs.align }
		},

		dir() {
			return this.node.attrs.dir || ''
		},
	},

	beforeMount() {
		this.isEditable = this.editor.isEditable
		this.editor.on('update', this.onUpdate)
	},

	beforeUnmount() {
		this.editor.off('update', this.onUpdate)
	},

	methods: {
		onUpdate({ editor }) {
			this.isEditable = editor.isEditable
		},

		setAlignCenter() {
			this.setAlign('center')
		},

		setAlignLeft() {
			this.setAlign('left')
		},

		setAlignRight() {
			this.setAlign('right')
		},

		setAlign(align) {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.setCellAttribute('align', align)
				.run()
			while (this.editor.commands.goToNextRow()) {
				this.editor.commands.setCellAttribute('align', align)
			}
			// Set focus back to first row
			this.editor.chain().setTextSelection(this.getPos()).focus().run()
			this.$refs.menu.closeMenu(false)
		},

		deleteColumn() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.deleteColumn()
				.run()
		},

		addColumnBefore() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.addColumnBefore()
				.run()
		},

		addColumnAfter() {
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos())
				.addColumnAfter()
				.run()
		},

		sortColumnAsc() {
			this.sortColumn('asc')
		},

		sortColumnDesc() {
			this.sortColumn('desc')
		},

		sortColumn(direction) {
			const pos = this.getPos()
			const cellNode = this.editor.state.doc.nodeAt(pos)
			this.editor.commands.sortColumn(direction, cellNode)
		},

		t,
	},
}
</script>

