<template>
	<NodeViewWrapper
		data-text-el="table-view"
		class="table-wrapper"
		:class="{ focused: isFocused, editable: isEditable }">
		<div class="table-scroll">
			<NodeViewContent class="content" as="table" />
		</div>
		<NcActions
			v-if="isEditable"
			forceMenu
			size="small"
			data-text-table-actions="settings"
			class="table-settings">
			<template #icon>
				<TableSettings />
			</template>
			<NcActionButton
				data-text-table-action="delete"
				closeAfterClick
				@click="deleteNode">
				<template #icon>
					<TrashCan />
				</template>
				{{ t('text', 'Delete this table') }}
			</NcActionButton>
		</NcActions>
		<NcButton
			v-if="isEditable"
			class="table-add-column"
			size="small"
			:aria-label="t('text', 'Add column after')"
			:title="t('text', 'Add column after')"
			@click="addColumnAfter">
			<template #icon>
				<TableAddColumnAfter />
			</template>
		</NcButton>
		<NcButton
			v-if="isEditable"
			class="table-add-row"
			size="small"
			wide
			:aria-label="t('text', 'Add row below')"
			:title="t('text', 'Add row below')"
			@click="addRowAfter">
			<template #icon>
				<TableAddRowAfter />
			</template>
		</NcButton>
	</NodeViewWrapper>
</template>

<script>
import { t } from '@nextcloud/l10n'
import { NodeViewContent, nodeViewProps, NodeViewWrapper } from '@tiptap/vue-3'
import NcActionButton from '@nextcloud/vue/components/NcActionButton'
import NcActions from '@nextcloud/vue/components/NcActions'
import NcButton from '@nextcloud/vue/components/NcButton'
import {
	TableAddColumnAfter,
	TableAddRowAfter,
	TableSettings,
	TrashCan,
} from '../../components/icons.js'

export default {
	name: 'TableView',
	components: {
		TableAddColumnAfter,
		TableAddRowAfter,
		NcActionButton,
		NcActions,
		NcButton,
		NodeViewWrapper,
		NodeViewContent,
		TableSettings,
		TrashCan,
	},

	props: nodeViewProps,

	data() {
		return {
			isEditable: false,
			isFocused: false,
		}
	},

	beforeMount() {
		this.isEditable = this.editor.isEditable
		this.editor.on('selectionUpdate', this.onSelectionUpdate)
		this.editor.on('update', this.onUpdate)
	},

	beforeUnmount() {
		this.editor.off('update', this.onUpdate)
		this.editor.off('selectionUpdate', this.onSelectionUpdate)
	},

	methods: {
		onUpdate({ editor }) {
			this.isEditable = editor.isEditable
		},

		onSelectionUpdate({ editor }) {
			const startOfCurrentNode = this.getPos()
			const endOfCurrentNode = startOfCurrentNode + this.node.nodeSize
			const { from, to } = editor.state.selection
			this.isFocused = from >= startOfCurrentNode && to <= endOfCurrentNode
		},

		addColumnAfter() {
			const headerRowNode = this.node.firstChild
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos() + headerRowNode.nodeSize - 1)
				.addColumnAfter()
				.setTextSelection(this.getPos() + headerRowNode.nodeSize + 1)
				.run()
		},

		addRowAfter() {
			const lastRowNode = this.node.lastChild
			this.editor
				.chain()
				.focus()
				.setTextSelection(this.getPos() + this.node.nodeSize - lastRowNode.nodeSize + 1)
				.addRowAfter()
				.setTextSelection(this.getPos() + this.node.nodeSize + 2)
				.run()
		},

		t,
	},
}
</script>

